'use strict';
const KEY='elo-juridico-demo-v1';
const seed=()=>({status:'intake',title:'Cobrança de serviço não contratado',narrative:'Cliente fictícia: Ana Exemplo. Relata cobranças por um serviço que afirma não ter contratado. A cobrança aparece em duas faturas demonstrativas. Informa ter procurado atendimento, sem solução até o momento. Todos os nomes, documentos e acontecimentos deste ambiente são inventados.',owner:'Lucas · estagiário',due:'2026-10-22',model:'Estrutura demonstrativa · petição inicial',instructions:'Organize a sequência dos fatos e relacione cada afirmação ao documento demonstrativo correspondente. Sinalize lacunas para a revisão. Não presuma fatos nem inclua fundamentos sem conferência da advogada.',draft:'PETIÇÃO INICIAL — RASCUNHO DEMONSTRATIVO\n\n1. QUALIFICAÇÃO\nAna Exemplo, pessoa inteiramente fictícia. Dados de qualificação pendentes de conferência.\n\n2. FATOS\nA cliente fictícia relata cobranças de serviço que afirma não ter contratado. Duas faturas demonstrativas foram listadas no caso.\n\n3. PONTOS PARA ANÁLISE DA ADVOGADA\nConfirmar a documentação, a sequência dos contatos e a adequação dos fundamentos jurídicos. Este exemplo não contém fundamentação validada.\n\n4. PEDIDOS\n[Definir os pedidos após análise jurídica pela advogada responsável.]\n\nMaterial de demonstração. Não utilizar em processo real.',checks:[false,false,false],comments:[],versions:[],events:[{text:'Atendimento demonstrativo registrado por Marina.',at:'Exemplo inicial'}]});
let s=seed();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved.draft==='string'&&Array.isArray(saved.events))s={...s,...saved}}catch{}let page='overview',role='lawyer';
const $=q=>document.querySelector(q),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={intake:'Aguardando distribuição',working:'Em elaboração',review:'Em revisão',changes:'Ajustes solicitados',approved:'Aprovado na simulação'};
const stamp=()=>new Date().toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch{toast('Armazenamento indisponível. Alterações permanecem apenas nesta sessão.')}}function event(t){s.events.unshift({text:t,at:stamp()});save()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',4000)}
function go(p){page=p;render();window.scrollTo(0,0)}
function button(t,act,cls=''){return `<button class="btn ${cls}" data-action="${act}">${t}</button>`}function status(){return `<span class="chip ${s.status==='intake'||s.status==='changes'?'amber':''}">${names[s.status]}</span>`}
function heading(eye,title,desc,act=''){return `<div class="topline"><div><span class="eyebrow">${eye}</span><h1>${title}</h1><p class="muted">${desc}</p></div>${act}</div>`}
function flow(){let n=['intake','working','review','approved'].indexOf(s.status);if(s.status==='changes')n=1;return `<div class="flow">${['Atendimento','Distribuição & elaboração','Revisão','Aprovação interna'].map((v,i)=>`<span class="${i===n?'current':''}">${String(i+1).padStart(2,'0')} ${v}</span>${i<3?'<i>→</i>':''}`).join('')}</div>`}
function overview(){return heading('TRABALHO EM CONJUNTO',role==='lawyer'?'Tudo começa com clareza.':'Seu próximo passo, sem ruído.',role==='lawyer'?'Distribua com contexto. Revise no mesmo lugar.':'Instruções, documentos e devolutivas reunidos no seu caso.',button('Abrir caso demonstrativo ↗','case','primary'))+`<div class="stats"><div class="stat highlight"><span>CASOS NO AMBIENTE</span><strong>01</strong><small>Um fluxo completo para experimentar</small></div><div class="stat"><span>AGUARDANDO DISTRIBUIÇÃO</span><strong>${s.status==='intake'?'01':'00'}</strong><small>Prontos para ganhar responsável</small></div><div class="stat"><span>EM ELABORAÇÃO</span><strong>${['working','changes'].includes(s.status)?'01':'00'}</strong><small>Contexto disponível para a equipe</small></div><div class="stat"><span>PARA REVISAR</span><strong>${s.status==='review'?'01':'00'}</strong><small>Uma devolutiva, uma nova versão</small></div></div><div class="columns"><section><div class="card"><div class="cardhead"><h2>Seu fluxo de trabalho</h2><span class="chip gray">1 caso fictício</span></div><div class="task"><div class="tasktop"><span class="kicker">ELO-001 · CONSUMIDOR · DEMONSTRAÇÃO</span>${status()}</div><h3>${esc(s.title)}</h3><p>${s.status==='intake'?'O atendimento está organizado. Falta definir quem faz o quê.':s.status==='review'?'A minuta foi enviada. Revise e deixe suas observações por seção.':s.status==='approved'?'O ciclo demonstrativo foi concluído. Nenhum protocolo foi realizado.':'A minuta e as orientações estão prontas para continuar.'}</p><div class="taskmeta"><span>◉ ${s.status==='intake'?'Sem responsável':esc(s.owner)}</span><span>◷ Entrega interna: ${esc(s.due.split('-').reverse().join('/'))}</span>${button('Continuar →',s.status==='intake'?'case':'draft','small')}</div></div></div><div class="card"><div class="cardhead"><h2>Últimos movimentos</h2><span class="kicker">REGISTRO LOCAL</span></div><div class="cardbody">${s.events.slice(0,3).map(e=>`<div class="dots"><span class="dot"></span><div>${esc(e.text)}<br><span class="muted">${esc(e.at)}</span></div></div>`).join('')}</div></div></section><aside><div class="card guide"><div class="cardbody"><span class="eyebrow">DE PONTA A PONTA</span><h2>Um caso.<br>Todo o contexto.</h2><p>Experimente a passagem de trabalho entre a advogada e o estagiário.</p><ol class="steps"><li><span class="number">1</span>Registre o atendimento</li><li><span class="number">2</span>Distribua com orientações</li><li><span class="number">3</span>Elabore e envie para revisão</li><li><span class="number">4</span>Comente, ajuste e aprove</li></ol>${button('Começar demonstração →','case','dark')}</div></div><p class="note">Este ambiente demonstra organização de trabalho. Não analisa mérito jurídico, calcula prazos judiciais nem substitui a revisão profissional.</p></aside></div>`}
function casePage(){return heading('ELO-001 / ATENDIMENTO','O contexto vem primeiro.','Um ponto de partida organizado para a próxima pessoa.',status())+flow()+`<div class="columns"><section><div class="card"><div class="cardhead"><h2>Resumo do atendimento</h2><span class="chip gray">Fictício</span></div><div class="cardbody"><label class="field">Título do caso<input id="caseTitle" maxlength="100" value="${esc(s.title)}" ${role==='intern'?'readonly':''}></label><label class="field">Relato demonstrativo<textarea id="narrative" rows="5" ${role==='intern'?'readonly':''}>${esc(s.narrative)}</textarea></label>${role==='lawyer'?button('Salvar atendimento','saveCase','small'):''}</div></div><div class="card"><div class="cardhead"><h2>Documentos do caso</h2><span class="kicker">APENAS METADADOS</span></div><div class="cardbody">${[['Faturas demonstrativas.pdf','2 páginas · exemplo fictício'],['Registro de atendimento.pdf','1 página · exemplo fictício']].map(d=>`<div class="docrow"><span class="docicon">PDF</span><div><strong>${d[0]}</strong><small>${d[1]}</small></div></div>`).join('')}<p class="muted" style="font-size:11px;margin-top:15px">Nenhum arquivo real está anexado. O protótipo não recebe uploads.</p></div></div></section><aside><div class="card"><div class="cardhead"><h2>Distribuir com clareza</h2></div><div class="cardbody"><label class="field">Responsável<select id="owner" ${role==='intern'?'disabled':''}><option>Lucas · estagiário</option><option>Clara · estagiária</option></select></label><label class="field">Entrega interna combinada<input type="date" id="due" value="${esc(s.due)}" ${role==='intern'?'readonly':''}></label><p class="muted" style="font-size:10px">Data ilustrativa de entrega da equipe, não prazo judicial.</p><label class="field">Modelo de referência<select id="model" ${role==='intern'?'disabled':''}><option>Estrutura demonstrativa · petição inicial</option><option>Estrutura demonstrativa · relatório de fatos</option></select></label><label class="field">Orientações para elaboração<textarea id="instructions" rows="5" ${role==='intern'?'readonly':''}>${esc(s.instructions)}</textarea></label>${role==='lawyer'?button(s.status==='intake'?'Distribuir tarefa →':'Salvar orientações','assign','primary'):button('Ir para elaboração →','draft','primary')}</div></div></aside></div>`}
function draftPage(){let editable=role==='intern'&&['working','changes'].includes(s.status);return heading('ELO-001 / ELABORAÇÃO','Uma minuta, uma conversa.','A revisão acompanha o documento, sem se perder no chat.',status())+`<div class="columns"><section><div class="card"><div class="cardhead"><h2>Minuta demonstrativa</h2><span class="chip gray">${s.versions.length?s.versions.length+' versão(ões) salva(s)':'Rascunho inicial'}</span></div><div class="editorbar"><span>${editable?'Edição habilitada · estagiário':'Leitura · '+(role==='lawyer'?'visão da advogada':'estado atual')}</span><span>Sem geração automática</span></div><div class="cardbody"><label class="field" for="draft">Texto da minuta · conteúdo apenas ilustrativo</label><textarea id="draft" class="editor" ${editable?'':'readonly'}>${esc(s.draft)}</textarea><div class="actions">${editable?button('Salvar rascunho','saveDraft')+button('Enviar para revisão →','submit','primary'):''}${role==='lawyer'&&s.status==='review'?button('Solicitar ajustes','return')+button('Aprovar na simulação','approve','primary'):''}${role==='lawyer'&&['working','changes'].includes(s.status)?button('Simular visão do estagiário →','switchIntern','primary'):''}${role==='intern'&&s.status==='review'?button('Simular visão da advogada →','switchLawyer','primary'):''}${s.status==='intake'?button('Distribuir antes de elaborar →','case','primary'):''}${s.status==='approved'?button('Ver histórico →','history'):''}</div><p class="muted" style="font-size:10px;margin-top:12px">A aprovação é apenas um estado do protótipo. Não valida o conteúdo nem envia documentos.</p></div></div></section><aside><div class="card"><div class="cardhead"><h2>O que precisa ser feito</h2></div><div class="cardbody"><p style="font-size:12px;white-space:pre-wrap">${esc(s.instructions)}</p><div class="note">Modelo: ${esc(s.model)}<br>Entrega interna: ${esc(s.due.split('-').reverse().join('/'))}</div><h3 style="margin-top:20px">Conferência ilustrativa</h3><p class="muted" style="font-size:10px">Marcações manuais e alertas por regras fixas. Não há análise jurídica ou IA.</p>${['Conferi o relato e os documentos de exemplo','Sinalizei informações ainda pendentes','Revisei a estrutura da minuta'].map((c,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${s.checks[i]?'checked':''} ${editable?'':'disabled'}><span>${c}</span></label>`).join('')}<div class="note" id="alert">${s.checks.every(Boolean)?'✓ Checklist manual concluído. A revisão profissional continua necessária.':`${s.checks.filter(x=>!x).length} item(ns) ainda não marcado(s). Isso não impede o envio para revisão.`}</div></div></div><div class="card"><div class="cardhead"><h2>Conversa por seção</h2><span class="chip gray">${s.comments.length}</span></div><div class="cardbody">${s.comments.length?s.comments.map((c,i)=>`<div class="comment"><small>${esc(c.by)} · ${esc(c.section)} · ${esc(c.at)}</small><p>${esc(c.text)}</p>${c.resolved?'<span class="chip gray">Tratado na simulação</span>':role==='intern'&&editable?button('Marcar como tratado','resolve:'+i,'small'):''}</div>`).join(''):'<p class="empty">As observações ficam junto da seção a que se referem.</p>'}${role==='lawyer'&&s.status==='review'?`<label class="field">Seção<select id="section"><option>Fatos</option><option>Qualificação</option><option>Fundamentos</option><option>Pedidos</option><option>Geral</option></select></label><label class="field">Comentário<textarea id="comment" placeholder="Ex.: detalhe a sequência dos contatos fictícios." maxlength="1500"></textarea></label>${button('Adicionar comentário','comment','small')}`:''}</div></div></aside></div>`}
function history(){return heading('ELO-001 / MEMÓRIA DO CASO','Cada passo fica registrado.','Acompanhe devolutivas e compare os textos salvos nesta demonstração.')+`<div class="columns"><div class="card"><div class="cardhead"><h2>Linha do tempo</h2></div><div class="cardbody"><div class="timeline">${s.events.map(e=>`<div class="event"><small>${esc(e.at)}</small><p>${esc(e.text)}</p></div>`).join('')}</div></div></div><div class="card"><div class="cardhead"><h2>Versões da minuta</h2></div><div class="cardbody">${s.versions.length?s.versions.map((v,i)=>`<div class="version"><div><strong>Versão ${i+1} · ${esc(v.label)}</strong><small>${esc(v.at)}</small></div>${button('Ler','version:'+i,'small')}</div>`).join(''):'<p class="empty">Salve um rascunho ou envie para revisão para registrar a primeira versão.</p>'}<p class="muted" style="font-size:10px;margin-top:18px">Histórico local de demonstração; não é uma trilha de auditoria certificada.</p></div></div></div>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent={overview:'Visão geral',case:'Caso demonstrativo',draft:'Área de elaboração',history:'Histórico e versões'}[page];$('#role').value=role;$('#role').options[1].textContent='Estagiário(a) · '+s.owner.split(' · ')[0];$('.user').textContent=role==='lawyer'?'MA':s.owner.slice(0,2).toUpperCase();$('#app').innerHTML=({overview,case:casePage,draft:draftPage,history}[page])();if($('#owner'))$('#owner').value=s.owner;if($('#model'))$('#model').value=s.model;}
function snapshot(label){s.versions.push({text:s.draft,label,at:stamp()})}
function captureDraft(){if($('#draft')&&!$('#draft').readOnly)s.draft=$('#draft').value}
function modal(title,content){$('#dialog').innerHTML=`<h2>${title}</h2>${content}<div class="actions"><button class="btn" id="closeDialog">Fechar</button></div>`;$('#dialog').showModal();$('#closeDialog').onclick=()=>$('#dialog').close()}
function action(a){if(['case','draft','history'].includes(a)){captureDraft();save();go(a);return}if(a==='switchIntern'||a==='switchLawyer'){role=a==='switchIntern'?'intern':'lawyer';render();return}if(a==='saveCase'){const title=$('#caseTitle').value.trim(),narrative=$('#narrative').value.trim();if(!title||!narrative)return toast('Preencha o título e o relato fictício.');s.title=title;s.narrative=narrative;event('Atendimento demonstrativo atualizado por Marina.');toast('Atendimento salvo neste navegador.');return}if(a==='assign'){if(!$('#caseTitle').value.trim()||!$('#narrative').value.trim())return toast('Preencha o título e o relato fictício.');s.title=$('#caseTitle').value.trim();s.narrative=$('#narrative').value.trim();if(!$('#due').value||!$('#instructions').value.trim())return toast('Informe a entrega interna e as orientações.');s.owner=$('#owner').value;s.due=$('#due').value;s.model=$('#model').value;s.instructions=$('#instructions').value.trim();if(s.status==='intake'){s.status='working';event('Marina distribuiu a tarefa para '+s.owner+'.');toast('Tarefa distribuída. Troque a visão para simular o estagiário.')}else{event('Marina atualizou as orientações da tarefa.');toast('Orientações salvas.')}render();return}if(a==='saveDraft'||a==='submit'){captureDraft();if(!s.draft.trim())return toast('Escreva uma minuta demonstrativa antes de continuar.');snapshot(a==='submit'?'Enviada para revisão':'Rascunho');if(a==='submit'){s.status='review';event('Minuta enviada para revisão de Marina.');toast('Minuta enviada. Simule a visão da advogada para revisar.')}else{event('Rascunho salvo por '+s.owner+'.');toast('Rascunho e versão salvos.')}render();return}if(a==='comment'){const t=$('#comment').value.trim();if(!t)return toast('Escreva um comentário antes de adicionar.');s.comments.push({text:t,section:$('#section').value,by:'Marina · advogada',at:stamp(),resolved:false});event('Marina comentou a seção '+$('#section').value+'.');render();toast('Comentário registrado na seção.');return}if(a==='return'){if(!s.comments.some(c=>!c.resolved))return toast('Adicione um comentário com o ajuste solicitado.');s.status='changes';event('Marina devolveu a minuta com ajustes solicitados.');render();toast('Ajustes solicitados. O estagiário já pode editar.');return}if(a==='approve'){s.status='approved';event('Marina aprovou a minuta na simulação. Nenhum documento foi enviado.');render();toast('Ciclo demonstrativo concluído. Nenhum protocolo realizado.');return}if(a.startsWith('resolve:')){captureDraft();s.comments[Number(a.split(':')[1])].resolved=true;event('Comentário marcado como tratado pelo estagiário.');render();return}if(a.startsWith('version:')){const i=Number(a.split(':')[1]);modal('Versão '+(i+1),`<p class="muted">${esc(s.versions[i].label)} · ${esc(s.versions[i].at)}</p><pre>${esc(s.versions[i].text)}</pre>`);}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b.dataset.action);const n=e.target.closest('[data-page]');if(n){captureDraft();save();go(n.dataset.page)}});document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){captureDraft();s.checks[Number(e.target.dataset.check)]=e.target.checked;save();$('#alert').textContent=s.checks.every(Boolean)?'✓ Checklist manual concluído. A revisão profissional continua necessária.':`${s.checks.filter(x=>!x).length} item(ns) ainda não marcado(s). Isso não impede o envio para revisão.`}});$('#role').onchange=e=>{captureDraft();save();role=e.target.value;render()};$('#reset').onclick=()=>{modal('Reiniciar demonstração?',`<p>Isso apagará apenas as alterações, comentários e versões deste protótipo neste navegador.</p><button class="btn primary" id="confirmReset">Reiniciar dados fictícios</button>`);$('#confirmReset').onclick=()=>{s=seed();save();role='lawyer';$('#dialog').close();go('overview');toast('Demonstração reiniciada.')}};window.addEventListener('beforeunload',()=>{captureDraft();save()});render();
